// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    Reentrancy_bonus c;
    function setUp() public { c = new Reentrancy_bonus(); }

    function testFuzz_property(uint256 seed) public {
        // keep domain wide; seed only shapes the fuzz space, the deciding
        // counterparty is the adversarial helper required by the spec
        vm.assume(seed < type(uint248).max);

        // fund c so reward payouts can succeed
        vm.deal(address(c), 1 ether);

        // adversarial re-entrant recipient: during its payout it re-enters
        // getFirstWithdrawalBonus(address(this)); if that re-entrant call
        // SUCCEEDS (possible only in the mutant, which never sets the lock)
        // it reverts, rejecting the payment and failing the outer withdrawal.
        ReentrantRecipient r = new ReentrantRecipient();

        bool ok;
        try c.getFirstWithdrawalBonus(address(r)) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: for any recipient, the bonus withdrawal flow completes.
        assertTrue(ok);
    }
}

contract ReentrantRecipient {
    fallback() external payable {
        (bool innerOk, ) = msg.sender.call(
            abi.encodeWithSignature("getFirstWithdrawalBonus(address)", address(this))
        );
        if (innerOk) {
            revert();
        }
    }
}
